<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('communication','edit');global $conn;$tenantId=(int)getCurrentTenantId();$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM communication_templates WHERE id=? AND tenant_id=?");$q->bind_param('ii',$id,$tenantId);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();if(!$row){http_response_code(404);exit('Template not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');$channel=$_POST['channel']??'sms';$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');$status=$_POST['status']??'active';if($name===''||$message==='')$error='Name and message are required.';else{$q=$conn->prepare("UPDATE communication_templates SET name=?,channel=?,subject=?,message=?,status=? WHERE id=? AND tenant_id=?");$q->bind_param('ssss sii',$name,$channel,$subject,$message,$status,$id,$tenantId);$q->bind_param('sssssii',$name,$channel,$subject,$message,$status,$id,$tenantId);if($q->execute())redirect('templates.php');$error=$q->error?:'Unable to update template.';$q->close();}}
$pageTitle='Edit Communication Template';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Edit Template</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Name</label><input name="name" required value="<?=e($row['name'])?>"></div><div class="form-group"><label>Channel</label><select name="channel"><?php foreach(['sms'=>'SMS','whatsapp'=>'WhatsApp','email'=>'Email'] as $k=>$v):?><option value="<?=$k?>" <?=$row['channel']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-group"><label>Subject</label><input name="subject" value="<?=e($row['subject'])?>"></div><div class="form-group"><label>Message</label><textarea name="message" rows="7" required><?=e($row['message'])?></textarea></div><div class="form-group"><label>Status</label><select name="status"><option value="active" <?=$row['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$row['status']!=='active'?'selected':''?>>Inactive</option></select></div><button type="submit">Update Template</button> <a href="templates.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>